import { useState, useEffect, useCallback, useRef } from 'react'
import { useNavigate } from 'react-router-dom'
import { SUPPORTED_REVEAL_THEMES } from 'revealjs-shared'
import {
  ChevronLeft,
  Save,
  Palette,
  Settings2,
  Zap,
  CheckCircle,
  XCircle,
  Loader2,
  Keyboard,
  RotateCcw,
  AlertTriangle,
  CloudUpload,
} from 'lucide-react'
import { testAIConnection } from '../utils/ai'
import { Button } from '../components/ui'
import { getShortcuts } from '../utils/default-keyboard-shortcut-definitions-registry'
import {
  loadOverrides,
  saveOverride,
  resetOverride,
  resetAll,
  detectConflict,
} from '../utils/shortcut-local-storage-persistence'
import { normalizeKey, isReservedChord } from '../utils/shortcut-normalizer'
import SyncModal from '../components/SyncModal'
import useSettingsDraft from './use-settings-draft'
import { DEFAULT_SETTINGS } from './settings-draft'
import SettingsConflict from './SettingsConflict'

const TRANSITIONS = ['none', 'fade', 'slide', 'convex', 'concave', 'zoom']

const PROVIDERS = [
  { value: 'openai', label: 'OpenAI', models: ['gpt-4o-mini', 'gpt-4o', 'gpt-4-turbo'] },
  {
    value: 'gemini',
    label: 'Google Gemini',
    models: ['gemini-2.0-flash', 'gemini-2.0-pro', 'gemini-1.5-flash'],
  },
  { value: 'custom', label: 'Custom (OpenAI-compatible)', models: [] },
]

const fieldClass =
  'w-full px-3 py-2 rounded-md border border-border bg-secondary text-text-primary text-sm focus:outline-none focus:border-accent'

export default function SettingsPage() {
  const navigate = useNavigate()
  const draftState = useSettingsDraft()
  const { settings, setSettings, loading, saving, saveMsg, loadError, handleSave, dirty, conflict } = draftState
  const [testStatus, setTestStatus] = useState(null) // null | 'testing' | 'ok' | 'fail'
  const [testError, setTestError] = useState('')
  const [shortcuts, setShortcuts] = useState([])
  const [overrides, setOverrides] = useState({})
  const [recordingId, setRecordingId] = useState(null) // which shortcut id is being recorded
  const [conflictId, setConflictId] = useState(null) // shortcut id that has a conflict
  const [conflictWith, setConflictWith] = useState(null) // what it's conflicting with
  const [reservedWarning, setReservedWarning] = useState(null) // reserved chord warning
  const [showSyncModal, setShowSyncModal] = useState(false)
  const recordCancelRef = useRef(null)


  // Load and refresh shortcut registry
  const refreshShortcuts = useCallback(() => {
    const loaded = loadOverrides()
    setOverrides(loaded)
    setShortcuts(getShortcuts(loaded))
  }, [])
  useEffect(() => {
    refreshShortcuts()
  }, [refreshShortcuts])

  // Global key listener for shortcut recording
  useEffect(() => {
    if (recordingId === null) return
    setConflictId(null)
    setConflictWith(null)
    setReservedWarning(null)

    const handleKeyDown = (e) => {
      e.preventDefault()
      e.stopPropagation()

      // Escape cancels recording
      if (e.key === 'Escape') {
        setRecordingId(null)
        return
      }

      const chord = normalizeKey(e)

      if (isReservedChord(chord)) {
        setReservedWarning(chord)
        return
      }

      const current = getShortcuts(overrides)
      const conflict = detectConflict(recordingId, chord, current)

      if (conflict) {
        const conflicting = current.find((s) => s.id !== recordingId && s.activeKey === chord)
        setConflictId(recordingId)
        setConflictWith(conflicting?.label || chord)
        return
      }

      // Save and exit recording mode
      saveOverride(recordingId, chord)
      setRecordingId(null)
      setReservedWarning(null)
      refreshShortcuts()
    }

    window.addEventListener('keydown', handleKeyDown, { capture: true })
    const cancelRecording = () => {
      window.removeEventListener('keydown', handleKeyDown, { capture: true })
      setRecordingId(null)
    }
    recordCancelRef.current = cancelRecording

    return () => {
      window.removeEventListener('keydown', handleKeyDown, { capture: true })
      if (recordCancelRef.current === cancelRecording) recordCancelRef.current = null
    }
  }, [recordingId, overrides, refreshShortcuts])

  const cancelShortcutRecording = () => {
    if (recordCancelRef.current) {
      recordCancelRef.current()
    } else {
      setRecordingId(null)
    }
  }

  const handleResetOne = (id) => {
    resetOverride(id)
    refreshShortcuts()
    if (recordingId === id) setRecordingId(null)
  }
  const handleResetAll = () => {
    resetAll()
    refreshShortcuts()
    setRecordingId(null)
  }
  const handleStartRecord = (id) => {
    setRecordingId(id)
    setConflictId(null)
    setConflictWith(null)
    setReservedWarning(null)
  }


  const handleTestConnection = async () => {
    setTestStatus('testing')
    setTestError('')
    try {
      await testAIConnection(settings.ai)
      setTestStatus('ok')
    } catch (err) {
      setTestStatus('fail')
      setTestError(err.message)
    }
  }

  const update = (key, val) => setSettings((s) => ({ ...(s || DEFAULT_SETTINGS), [key]: val }))
  const updateAI = (key, val) =>
    setSettings((s) => ({
      ...(s || DEFAULT_SETTINGS),
      ai: { ...(s?.ai || DEFAULT_SETTINGS.ai), [key]: val },
    }))
  const handleProviderChange = (providerValue) => {
    const provider = PROVIDERS.find((candidate) => candidate.value === providerValue) || PROVIDERS[0]
    setSettings((current) => {
      const ai = current?.ai || DEFAULT_SETTINGS.ai
      const model = provider.models.includes(ai.model) ? ai.model : provider.models[0] || ai.model
      return {
        ...(current || DEFAULT_SETTINGS),
        ai: { ...ai, provider: provider.value, model },
      }
    })
  }


  const currentProvider =
    PROVIDERS.find((p) => p.value === (settings?.ai?.provider || 'openai')) || PROVIDERS[0]

  if (loading) {
    return (
      <div className="h-screen flex items-center justify-center bg-panel">
        <p className="text-text-muted">Loading settings...</p>
      </div>
    )
  }

  return (
    <div className="h-full flex flex-col bg-panel">
      <div className="flex items-center justify-between px-6 h-14 border-b border-border bg-secondary shrink-0">
        <div className="flex items-center gap-3">
          <Button
            variant="secondary"
            onClick={() => {
              cancelShortcutRecording()
              navigate('/')
            }}
            className="px-2.5 py-1.5"
          >
            <ChevronLeft size={16} />
          </Button>
          <h1 className="text-xl">
            <Settings2 size={20} className="inline-block mr-2 align-middle" />
            Settings
          </h1>
        </div>
        <div className="flex items-center gap-2">
          {loadError && (
            <span className="text-[13px] text-danger" role="alert">
              {loadError}
            </span>
          )}
          {(saveMsg || dirty) && (
            <span
              className={`text-[13px] ${saveMsg.startsWith('Error') ? 'text-danger' : 'text-success'}`}
              role={saveMsg.startsWith('Error') ? 'alert' : 'status'}
              aria-label="Settings save status"
              aria-live={saveMsg.startsWith('Error') ? 'assertive' : 'polite'}
            >
              {saveMsg || 'Unsaved changes'}
            </span>
          )}
          <Button variant="primary" onClick={handleSave} disabled={saving || !!loadError || !!conflict}>
            <Save size={14} />
            {saving ? 'Saving...' : 'Save'}
          </Button>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto pt-7 px-8 pb-7 max-w-[640px] mx-auto">
        <SettingsConflict {...draftState} cancelShortcutRecording={cancelShortcutRecording} />
        {/* AI Configuration */}
        <section className="mb-8">
          <h2 className="flex items-center gap-2 mb-4">
            <Zap size={18} /> AI Configuration
          </h2>

          <div className="flex flex-col gap-4">
            {/* Provider */}
            <div>
              <label htmlFor="ai-provider" className="text-[13px] text-text-muted block mb-1.5">
                Provider
              </label>
              <select
                id="ai-provider"
                value={settings?.ai?.provider || 'openai'}
                onChange={(e) => handleProviderChange(e.target.value)}
                className={fieldClass}
              >
                {PROVIDERS.map((p) => (
                  <option key={p.value} value={p.value}>
                    {p.label}
                  </option>
                ))}
              </select>
            </div>

            {/* API Key (not for custom without key) */}
            {currentProvider.value !== 'custom' && (
              <div>
                <label htmlFor="ai-api-key" className="text-[13px] text-text-muted block mb-1.5">
                  API Key
                </label>
                <input
                  id="ai-api-key"
                  type="password"
                  value={settings?.ai?.apiKey || ''}
                  onChange={(e) => updateAI('apiKey', e.target.value)}
                  placeholder={`Enter your ${currentProvider.label} API key`}
                  className={fieldClass}
                />
              </div>
            )}

            {/* Model selector for known providers */}
            {currentProvider.models.length > 0 && (
              <div>
                <label htmlFor="ai-model" className="text-[13px] text-text-muted block mb-1.5">
                  Model
                </label>
                <select
                  id="ai-model"
                  value={settings?.ai?.model || currentProvider.models[0]}
                  onChange={(e) => updateAI('model', e.target.value)}
                  className={fieldClass}
                >
                  {currentProvider.models.map((m) => (
                    <option key={m} value={m}>
                      {m}
                    </option>
                  ))}
                </select>
              </div>
            )}

            {/* Custom endpoint */}
            {currentProvider.value === 'custom' && (
              <>
                <div>
                  <label
                    htmlFor="ai-custom-endpoint"
                    className="text-[13px] text-text-muted block mb-1.5"
                  >
                    Endpoint URL
                  </label>
                  <input
                    id="ai-custom-endpoint"
                    type="text"
                    value={settings?.ai?.customEndpoint || ''}
                    onChange={(e) => updateAI('customEndpoint', e.target.value)}
                    placeholder="http://localhost:11434/v1"
                    className={fieldClass}
                  />
                  <p className="text-xs text-text-muted mt-1">
                    OpenAI-compatible endpoint (Ollama, LM Studio, vLLM, etc.)
                  </p>
                </div>
                <div>
                  <label
                    htmlFor="ai-custom-model"
                    className="text-[13px] text-text-muted block mb-1.5"
                  >
                    Model Name
                  </label>
                  <input
                    id="ai-custom-model"
                    type="text"
                    value={settings?.ai?.customModel || ''}
                    onChange={(e) => updateAI('customModel', e.target.value)}
                    placeholder="llama3.2"
                    className={fieldClass}
                  />
                </div>
              </>
            )}

            {/* Test Connection */}
            <div className="flex items-center gap-3">
              <Button
                variant="secondary"
                onClick={handleTestConnection}
                disabled={testStatus === 'testing'}
                className="flex items-center gap-1.5"
              >
                {testStatus === 'testing' ? (
                  <Loader2 size={14} className="animate-spin" />
                ) : (
                  <Zap size={14} />
                )}
                Test Connection
              </Button>
              {testStatus === 'ok' && (
                <span
                  role="status"
                  aria-label="AI connection status"
                  aria-live="polite"
                  className="text-success text-[13px] flex items-center gap-1"
                >
                  <CheckCircle size={14} /> Connected
                </span>
              )}
              {testStatus === 'fail' && (
                <span
                  role="status"
                  aria-label="AI connection status"
                  aria-live="polite"
                  className="text-danger text-[13px] flex items-center gap-1"
                >
                  <XCircle size={14} /> {testError || 'Failed'}
                </span>
              )}
            </div>
          </div>
        </section>

        {/* Keyboard Shortcuts */}
        <section className="mb-8">
          <div className="flex items-center justify-between mb-4">
            <h2 className="flex items-center gap-2">
              <Keyboard size={18} /> Keyboard Shortcuts
            </h2>
            <Button
              variant="ghost"
              size="sm"
              onClick={handleResetAll}
              className="text-[13px] flex items-center gap-1.5 text-text-muted hover:text-danger"
            >
              <RotateCcw size={13} /> Reset All
            </Button>
          </div>

          {recordingId !== null && (
            <div className="mb-4 px-4 py-3 rounded-md border border-accent bg-accent/10 text-[13px]">
              <span className="font-medium text-accent">Recording shortcut —</span> Press any key
              combination, or{' '}
              <kbd className="px-1.5 py-0.5 rounded bg-accent/20 text-accent font-mono text-xs">
                Esc
              </kbd>{' '}
              to cancel
            </div>
          )}

          {reservedWarning && (
            <div className="mb-4 px-4 py-3 rounded-md border border-amber-500 bg-amber-500/10 text-[13px] flex items-center gap-2">
              <AlertTriangle size={14} className="text-amber-500 shrink-0" />
              <span>
                <span className="font-medium text-amber-500">{reservedWarning}</span> is reserved by
                the browser and cannot be used.
              </span>
            </div>
          )}

          {conflictId && (
            <div className="mb-4 px-4 py-3 rounded-md border border-amber-500 bg-amber-500/10 text-[13px] flex items-center gap-2">
              <AlertTriangle size={14} className="text-amber-500 shrink-0" />
              <span>
                Shortcut <span className="font-mono font-medium">{conflictWith}</span> is already
                assigned to another command.
              </span>
            </div>
          )}

          {['clipboard', 'navigation', 'view'].map((category) => {
            const items = shortcuts.filter((s) => s.category === category)
            if (items.length === 0) return null
            const labels = { clipboard: 'Clipboard', navigation: 'Navigation', view: 'View' }
            return (
              <div key={category} className="mb-5">
                <h3 className="text-[12px] text-text-muted uppercase tracking-wider mb-2 font-medium">
                  {labels[category]}
                </h3>
                <div className="flex flex-col gap-1">
                  {items.map((shortcut) => {
                    const isRecording = recordingId === shortcut.id
                    const isOverridden = shortcut.activeKey !== shortcut.defaultKey
                    return (
                      <div
                        key={shortcut.id}
                        className="flex items-center justify-between py-1.5 px-3 rounded hover:bg-secondary/50 group"
                      >
                        <span className="text-[13px] text-text-primary">{shortcut.label}</span>
                        <div className="flex items-center gap-2">
                          {isRecording ? (
                            <span className="text-[12px] text-accent font-medium animate-pulse">
                              Press a key...
                            </span>
                          ) : (
                            <kbd className="text-[12px] px-2 py-0.5 rounded border border-border bg-secondary font-mono text-text-secondary">
                              {shortcut.activeKey}
                            </kbd>
                          )}
                          <Button
                            variant="ghost"
                            size="sm"
                            onClick={() =>
                              isRecording ? setRecordingId(null) : handleStartRecord(shortcut.id)
                            }
                            aria-label={`${isRecording ? 'Cancel editing' : 'Edit'} ${shortcut.label}`}
                            className={`h-6 px-2 text-[11px] ${
                              isRecording
                                ? 'text-danger hover:text-danger'
                                : 'text-text-muted opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 hover:text-accent'
                            }`}
                          >
                            {isRecording ? 'Cancel' : 'Edit'}
                          </Button>
                          {isOverridden && (
                            <Button
                              variant="ghost"
                              size="sm"
                              onClick={() => handleResetOne(shortcut.id)}
                              className="h-6 px-1.5 text-[11px] text-text-muted opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 hover:text-danger"
                              title="Reset to default"
                              aria-label={`Reset ${shortcut.label} to default`}
                            >
                              <RotateCcw size={11} />
                            </Button>
                          )}
                        </div>
                      </div>
                    )
                  })}
                </div>
              </div>
            )
          })}
          <p className="text-[11px] text-text-muted mt-1">
            Click Edit to record a new shortcut. Conflicts are detected automatically.
          </p>
        </section>

        {/* Default Preferences */}
        <section className="mb-8">
          <h2 className="flex items-center gap-2 mb-4">
            <Palette size={18} /> Default Preferences
          </h2>
          <div className="flex flex-col gap-4">
            <div>
              <label htmlFor="default-theme" className="text-[13px] text-text-muted block mb-1.5">
                Default Theme
              </label>
              <select
                id="default-theme"
                value={settings?.defaultTheme || 'black'}
                onChange={(e) => update('defaultTheme', e.target.value)}
                className={fieldClass}
              >
                {SUPPORTED_REVEAL_THEMES.map((t) => (
                  <option key={t} value={t}>
                    {t.charAt(0).toUpperCase() + t.slice(1)}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label
                htmlFor="default-transition"
                className="text-[13px] text-text-muted block mb-1.5"
              >
                Default Transition
              </label>
              <select
                id="default-transition"
                value={settings?.defaultTransition || 'slide'}
                onChange={(e) => update('defaultTransition', e.target.value)}
                className={fieldClass}
              >
                {TRANSITIONS.map((t) => (
                  <option key={t} value={t}>
                    {t.charAt(0).toUpperCase() + t.slice(1)}
                  </option>
                ))}
              </select>
            </div>
          </div>
        </section>

        {/* Cloud Sync */}
        <section className="mb-8">
          <h2 className="flex items-center gap-2 mb-4">
            <CloudUpload size={18} /> Cloud Sync
          </h2>
          <Button
            variant="secondary"
            data-testid="settings-open-sync"
            onClick={() => {
              cancelShortcutRecording()
              setShowSyncModal(true)
            }}
            className="flex items-center gap-1.5"
          >
            <CloudUpload size={14} />
            Open Sync
          </Button>
        </section>
      </div>

      {showSyncModal && <SyncModal onClose={() => setShowSyncModal(false)} />}
    </div>
  )
}

import { useEffect, useRef, useState } from 'react'
import {
  DEFAULT_SETTINGS, editableSettings, acceptedDraft, keyIntent, settingsDirty,
  conflictFields, rebasedDraft,
} from './settings-draft'

export default function useSettingsDraft() {
  const [settings, renderDraft] = useState(DEFAULT_SETTINGS)
  const draft = useRef(DEFAULT_SETTINGS)
  const [baseline, setBaseline] = useState(null)
  const [revision, setRevision] = useState(null)
  const [loading, setLoading] = useState(true)
  const [saving, setSaving] = useState(false)
  const [saveMsg, setSaveMsg] = useState('')
  const [saveSucceeded, setSaveSucceeded] = useState(false)
  const [latestLoaded, setLatestLoaded] = useState(false)
  const [loadError, setLoadError] = useState('')
  const [conflict, setConflict] = useState(null)
  const [choices, setChoices] = useState({})
  const mounted = useRef(false)
  const busy = useRef(false)
  const requests = useRef(new Set())
  const setSettings = (update) => {
    const next = typeof update === 'function' ? update(draft.current) : update
    draft.current = next
    renderDraft(next)
  }
  const request = async (options) => {
    const controller = new AbortController()
    requests.current.add(controller)
    try {
      return await fetch('/api/settings', { ...options, signal: controller.signal })
    } finally { requests.current.delete(controller) }
  }
  useEffect(() => {
    let active = true
    mounted.current = true
    ;(async () => {
      try {
        const response = await request()
        if (!active) return
        if (!response.ok) throw new Error('Failed to load settings')
        const data = await response.json()
        if (!active) return
        const accepted = editableSettings(data)
        setSettings(accepted)
        setBaseline(accepted)
        setRevision(data.settingsRevision ?? 0)
      } catch (error) {
        if (active) setLoadError(error.message || 'Failed to load settings')
      } finally { if (active) setLoading(false) }
    })()
    return () => {
      active = false
      mounted.current = false
      for (const controller of requests.current) controller.abort()
    }
  }, [])

  const handleSave = async () => {
    if (busy.current || !baseline || conflict) return
    busy.current = true
    setSaving(true)
    setSaveMsg('')
    setSaveSucceeded(false)
    setLatestLoaded(false)
    const submitted = draft.current
    const body = { ...submitted, ai: { ...submitted.ai } }
    if (keyIntent(submitted, baseline) === 'unchanged') delete body.ai.apiKey
    try {
      const response = await request({ method: 'PUT', headers: {
        'Content-Type': 'application/json', 'If-Match': `"${revision}"`,
      }, body: JSON.stringify(body) })
      if (!mounted.current) return
      if (response.status === 412) {
        setConflict({ baseline, latest: null, revision: null })
        setSaveMsg('Error: Settings changed on the server. Review latest before saving.')
        return
      }
      if (!response.ok) throw new Error('Save failed')
      const data = await response.json()
      if (!mounted.current) return
      const accepted = editableSettings(data)
      const current = acceptedDraft(draft.current, submitted, accepted)
      setBaseline(accepted)
      setRevision(data.settingsRevision)
      setSettings(current)
      setSaveSucceeded(true)
    } catch (error) {
      if (mounted.current) setSaveMsg('Error: ' + error.message)
    } finally {
      busy.current = false
      if (mounted.current) setSaving(false)
    }
  }
  const reviewLatest = async () => {
    if (busy.current) return
    busy.current = true
    try {
      const response = await request()
      if (!response.ok) throw new Error('Failed to load latest settings')
      const data = await response.json()
      if (!mounted.current) return
      setConflict(previous => ({ ...previous, latest: editableSettings(data), revision: data.settingsRevision }))
      setChoices({})
    } catch (error) { if (mounted.current) setSaveMsg('Error: ' + error.message) }
    finally { busy.current = false }
  }
  const fields = conflict?.latest ? conflictFields(settings, conflict.baseline, conflict.latest) : []
  const resolveConflict = (reload = false) => {
    if (!conflict?.latest || (!reload && fields.some(field => !choices[field]))) return
    setSettings(reload ? conflict.latest : rebasedDraft(draft.current, conflict.baseline, conflict.latest, choices))
    setBaseline(conflict.latest)
    setRevision(conflict.revision)
    setConflict(null)
    setSaveSucceeded(false)
    setLatestLoaded(reload)
    setSaveMsg(reload ? '' : 'Draft rebased; save to apply your changes.')
  }
  const dirty = baseline ? settingsDirty(settings, baseline) : false
  const status = saveMsg || (saveSucceeded
    ? dirty ? 'Saved submitted snapshot; unsaved changes remain.' : 'Settings saved!'
    : latestLoaded ? dirty ? 'Unsaved changes' : 'Latest settings loaded.' : '')
  return { settings, setSettings, baseline, loading, saving, saveMsg: status, loadError, handleSave,
    conflict, choices, setChoices, reviewLatest, fields, resolveConflict, dirty }
}

const { RECORD_SCHEMA_VERSION, hashRecord, validateOwner } = require('./schemas')
const { queueCompatibilityRemoval, queueCompatibilityUpsert } = require('../compatibility-outbox')
const { createMatrixAuthoritySubjects } = require('../canonical-feature-matrix')
const { canonicalEditableSnapshot } = require('../canonical-snapshot')
const { rebindSourceMap } = require('../source-map')
const { MUTATION_OPERATIONS } = require('../mutation-operation-scope')
const { resolveEditedExportContext } = require('../validated-edited-export-context')
const { getTrustedImportMetadata } = require('../trusted-import-metadata')
const { mergeCompatibilityPresentation } = require('../compatibility-view')

const clone = (value) => structuredClone(value)
const revisionIdsFor = (head) => new Set([
  head.originalRevisionId,
  head.projectionRevisionId,
  head.packageRevisionId,
  head.sourceMapRevisionId,
  head.journalRevisionId,
].filter(Boolean))

function committedAuthority(state, head) {
  return [...(state.mutationResults || [])].reverse().find((result) =>
    result.presentationId === head.presentationId &&
    result.packageRevisionId === head.packageRevisionId &&
    result.state === 'committed' && result.projection && result.sourceMap &&
    (head.projectionRevisionId === hashRecord(result.projection) &&
      head.sourceMapRevisionId === hashRecord(result.sourceMap)) &&
    (result.journal?.journalHash ?? null) === (head.journalRevisionId ?? null) &&
    (result.operation === undefined ||
      result.operation === MUTATION_OPERATIONS.PACKAGE_IMPORT ||
      result.operation === MUTATION_OPERATIONS.VALIDATED_EDITED_EXPORT)
  ) || null
}

function comparableTemplateProjection(value) {
  const projection = canonicalEditableSnapshot(value)
  for (const key of ['id', 'title', 'description', 'isTemplate']) delete projection[key]
  return projection
}

function rebindAuthority(authority, presentationId, generation, idempotencyKey, options = {}) {
  if (!authority) return null
  const projection = options.projection
    ? { ...canonicalEditableSnapshot(options.projection), id: presentationId }
    : { ...clone(authority.projection), id: presentationId }
  const sourceMap = rebindSourceMap(authority.sourceMap, {
    presentationId,
    revisionId: authority.packageRevisionId,
    packageGeneration: generation,
  })
  const result = {
    ...clone(authority),
    presentationId,
    idempotencyKey,
    generation,
    packageRevisionId: authority.packageRevisionId,
    projection,
    sourceMap,
    requestHash: hashRecord({ lifecycle: idempotencyKey, projection, sourceMap }),
    state: 'committed',
  }
  delete result.requestIdentity
  return result
}

function lifecycleError(code, message) {
  return Object.assign(new Error(message), {
    code,
    status: code === 'PACKAGE_PENDING_PROJECTION' || code === 'STALE_GENERATION'
      ? 409
      : code === 'CURRENT_SOURCE_AUTHORITY_UNAVAILABLE' ? 422 : 500,
    ...(code === 'STALE_GENERATION' ? { retryable: true } : {}),
  })
}

function assertHeadUnchanged(next, expected, presentationId) {
  const actual = next.heads.find((head) => head.presentationId === presentationId)
  if (!actual || hashRecord(actual) !== hashRecord(expected)) {
    throw lifecycleError('STALE_GENERATION', 'Package lifecycle source head changed')
  }
}

function addOwner(next, revisionId, owner, retainedHead) {
  if (next.owners.some((item) =>
    item.revisionId === revisionId &&
    item.ownerType === owner.ownerType &&
    item.ownerId === owner.ownerId
  )) return
  next.owners.push({
    schemaVersion: RECORD_SCHEMA_VERSION,
    revisionId,
    ...owner,
    ...(retainedHead ? { retainedHead: clone(retainedHead) } : {}),
  })
}

async function admit(store, options) {
  if (options.admissionPreflight) {
    await options.admissionPreflight(store.getState())
  }
}

async function duplicatePresentationOwner(store, sourceId, destinationId, options = {}) {
  const owner = validateOwner({ ownerType: 'presentation', ownerId: destinationId })
  const source = store.metadata.state.heads.find((head) => head.presentationId === sourceId)
  if (!source) return null
  if (Object.hasOwn(options, 'expectedSourceHead') && options.expectedSourceHead === null) {
    throw lifecycleError('STALE_GENERATION', 'Package lifecycle source head appeared')
  }
  const expectedSourceHead = options.expectedSourceHead || source
  if (hashRecord(source) !== hashRecord(expectedSourceHead)) {
    throw lifecycleError('STALE_GENERATION', 'Package lifecycle source head changed')
  }
  if (source.pendingJournalHash !== undefined) {
    throw lifecycleError(
      'PACKAGE_PENDING_PROJECTION',
      'Cannot duplicate a presentation with a pending package projection'
    )
  }
  const authority = committedAuthority(store.metadata.state, source)
  await admit(store, options)
  await store.mutate((next) => {
    assertHeadUnchanged(next, expectedSourceHead, sourceId)
    const destination = {
      ...clone(source),
      presentationId: destinationId,
      generation: 1,
      predecessorId: null,
      matrixAuthorityEpoch: next.matrixAuthorityEpoch,
      matrixAuthoritySubjects: createMatrixAuthoritySubjects(undefined, next.matrixAuthorityEpoch),
      fencingEpoch: store.fencingEpoch,
    }
    delete destination.pendingJournalHash
    if (authority) {
      const rebound = rebindAuthority(
        authority,
        destinationId,
        destination.generation,
        `lifecycle-duplicate-${hashRecord({ sourceId, destinationId, revisionId: source.packageRevisionId })}`,
        { projection: options.projection }
      )
      destination.projectionRevisionId = hashRecord(rebound.projection)
      destination.sourceMapRevisionId = hashRecord(rebound.sourceMap)
      if (destination.packageRevisionId === destination.originalRevisionId) {
        destination.journalRevisionId = null
      }
      next.mutationResults.push(rebound)
    }
    for (const revisionId of revisionIdsFor(destination)) addOwner(next, revisionId, owner)
    next.heads.push(destination)
  }, options)
  return store.metadata.state.heads.find((head) => head.presentationId === destinationId)
}

async function quarantinePresentation(store, presentationId, options = {}) {
  const head = store.metadata.state.heads.find((item) => item.presentationId === presentationId)
  if (!head) {
    if (options.expectedHead) {
      throw lifecycleError('STALE_GENERATION', 'Package lifecycle source head changed')
    }
    return null
  }
  const expectedHead = options.expectedHead || head
  if (hashRecord(head) !== hashRecord(expectedHead)) {
    throw lifecycleError('STALE_GENERATION', 'Package lifecycle source head changed')
  }
  await admit(store, options)
  await store.mutate((next) => {
    assertHeadUnchanged(next, expectedHead, presentationId)
    next.owners = next.owners.filter(
      (item) => item.ownerType !== 'presentation' || item.ownerId !== presentationId
    )
    next.heads = next.heads.filter((item) => item.presentationId !== presentationId)
    if (options.compatibilityRemove) {
      queueCompatibilityRemoval(next, {
        presentationId,
        generation: expectedHead.generation,
      })
    }
  }, options)
  return clone(expectedHead)
}

async function restoreQuarantinedHead(
  store,
  retainedOwner,
  presentationId,
  options = {}
) {
  validateOwner(retainedOwner)
  const retained = retainedHeadForOwner(store.metadata.state, retainedOwner)
  if (!retained || retained.retainedHead.presentationId !== presentationId) return null
  const existing = store.metadata.state.heads.find((item) => item.presentationId === presentationId)
  if (existing) {
    if (hashRecord(existing) !== hashRecord(retained.retainedHead)) {
      throw lifecycleError('STALE_GENERATION', 'Package lifecycle restored head changed')
    }
    return clone(existing)
  }

  await admit(store, options)
  await store.mutate((next) => {
    const liveRetained = retainedHeadForOwner(next, retainedOwner)
    if (!liveRetained || liveRetained.retainedHead.presentationId !== presentationId ||
        hashRecord(liveRetained.retainedHead) !== hashRecord(retained.retainedHead)) {
      throw lifecycleError('STALE_GENERATION', 'Package lifecycle retained head changed')
    }
    if (next.heads.some((item) => item.presentationId === presentationId)) {
      throw lifecycleError('STALE_GENERATION', 'Package lifecycle restored head already exists')
    }
    const restoredHead = clone(liveRetained.retainedHead)
    next.heads.push(restoredHead)
    for (const revisionId of liveRetained.retainedRevisionIds) {
      addOwner(next, revisionId, {
        ownerType: 'presentation',
        ownerId: presentationId,
      })
    }
    if (options.compatibilityPresentation) {
      queueCompatibilityUpsert(next, {
        presentationId,
        generation: restoredHead.generation,
        updatedAt: options.updatedAt || options.compatibilityPresentation.updatedAt,
        presentation: {
          ...clone(options.compatibilityPresentation),
          id: presentationId,
          pptxAggregateHead: clone(restoredHead),
        },
      })
    }
  }, options)
  return store.metadata.state.heads.find((item) => item.presentationId === presentationId)
}

async function retainHead(store, owner, presentationId, options = {}) {
  validateOwner(owner)
  const head = store.metadata.state.heads.find((item) => item.presentationId === presentationId)
  if (!head) {
    if (options.expectedHead) {
      throw lifecycleError('STALE_GENERATION', 'Package lifecycle source head changed')
    }
    return null
  }
  const expectedHead = options.expectedHead || head
  if (hashRecord(head) !== hashRecord(expectedHead)) {
    throw lifecycleError('STALE_GENERATION', 'Package lifecycle source head changed')
  }
  await admit(store, options)
  await store.mutate((next) => {
    assertHeadUnchanged(next, expectedHead, presentationId)
    // One retained owner must describe one aggregate head so retries cannot
    // leave an older head available for a later restore.
    next.owners = next.owners.filter((item) =>
      item.ownerType !== owner.ownerType || item.ownerId !== owner.ownerId
    )
    for (const revisionId of revisionIdsFor(expectedHead)) {
      addOwner(next, revisionId, owner, expectedHead)
    }
  }, options)
  return clone(expectedHead)
}

function hasRetainedRevisionIntegrity(state, retainedHead, retainedOwner, requireOwnerEntries = true) {
  const packageRevisionIds = new Set([
    retainedHead.originalRevisionId,
    retainedHead.packageRevisionId,
  ].filter(Boolean))
  for (const revisionId of packageRevisionIds) {
    const revision = state.revisions.find((item) => item.id === revisionId)
    if (!revision || !state.blobs.some((blob) => blob.sha256 === revision.blobSha256) ||
        (requireOwnerEntries && !state.owners.some((owner) =>
          owner.ownerType === retainedOwner.ownerType &&
          owner.ownerId === retainedOwner.ownerId &&
          owner.revisionId === revisionId
        ))) return false
  }

  const authorityResults = (state.mutationResults || []).filter((result) =>
    result.presentationId === retainedHead.presentationId &&
    result.packageRevisionId === retainedHead.packageRevisionId
  )
  if (retainedHead.projectionRevisionId && !authorityResults.some((result) =>
    result.projection && hashRecord(result.projection) === retainedHead.projectionRevisionId
  )) return false
  if (retainedHead.sourceMapRevisionId && !authorityResults.some((result) =>
    result.sourceMap && hashRecord(result.sourceMap) === retainedHead.sourceMapRevisionId
  )) return false
  if (retainedHead.journalRevisionId && !authorityResults.some((result) =>
    result.journal?.journalHash === retainedHead.journalRevisionId
  )) return false
  return true
}

function retainedHeadForOwner(state, retainedOwner) {
  const retainedOwners = state.owners.filter((item) =>
    item.ownerType === retainedOwner.ownerType && item.ownerId === retainedOwner.ownerId
  )
  const retainedHead = retainedOwners.find((item) => item.retainedHead)?.retainedHead
  if (!retainedHead) return null

  const retainedRevisionIds = revisionIdsFor(retainedHead)
  const retainedHeadId = hashRecord(retainedHead)
  const ownersForRetainedHead = retainedOwners.filter((item) =>
    item.retainedHead && hashRecord(item.retainedHead) === retainedHeadId
  )
  if (![...retainedRevisionIds].every((revisionId) => ownersForRetainedHead.some((item) =>
    item.revisionId === revisionId
  )) || !hasRetainedRevisionIntegrity(state, retainedHead, retainedOwner)) return null
  return { retainedHead, retainedRevisionIds }
}

function restorableHead(state, presentationId, retainedOwner) {
  const retained = retainedHeadForOwner(state, retainedOwner)
  const current = state.heads.find((item) => item.presentationId === presentationId)
  if (!retained || !current || retained.retainedHead.presentationId !== presentationId) return null
  return { ...retained, current }
}

async function instantiateRetainedHead(store, retainedOwner, destinationId, options = {}) {
  validateOwner(retainedOwner)
  const owner = validateOwner({ ownerType: 'presentation', ownerId: destinationId })
  const retained = retainedHeadForOwner(store.metadata.state, retainedOwner)
  if (!retained) return null
  const { retainedHead, retainedRevisionIds } = retained
  if (retainedHead.pendingJournalHash !== undefined) {
    throw lifecycleError(
      'PACKAGE_PENDING_PROJECTION',
      'Cannot instantiate a template with a pending package projection'
    )
  }
  const authority = committedAuthority(store.metadata.state, retainedHead)
  if (!authority && (retainedHead.projectionRevisionId || retainedHead.sourceMapRevisionId)) {
    throw lifecycleError(
      'CURRENT_SOURCE_AUTHORITY_UNAVAILABLE',
      'Package lifecycle retained authority is unavailable'
    )
  }
  if (authority && options.requireProjectionMatch) {
    try {
      if (hashRecord(comparableTemplateProjection(options.projection)) !==
          hashRecord(comparableTemplateProjection(authority.projection))) {
        throw lifecycleError(
          'CURRENT_SOURCE_AUTHORITY_UNAVAILABLE',
          'Package lifecycle template projection changed'
        )
      }
    } catch (error) {
      if (error.code === 'CURRENT_SOURCE_AUTHORITY_UNAVAILABLE') throw error
      throw lifecycleError(
        'CURRENT_SOURCE_AUTHORITY_UNAVAILABLE',
        'Package lifecycle template projection is invalid'
      )
    }
  }
  if (store.metadata.state.heads.some((head) => head.presentationId === destinationId)) {
    throw lifecycleError('STALE_GENERATION', 'Package lifecycle destination already exists')
  }

  await admit(store, options)
  await store.mutate((next) => {
    const liveRetained = retainedHeadForOwner(next, retainedOwner)
    if (!liveRetained || hashRecord(liveRetained.retainedHead) !== hashRecord(retainedHead)) {
      throw lifecycleError('STALE_GENERATION', 'Package lifecycle retained head changed')
    }
    if (next.heads.some((head) => head.presentationId === destinationId)) {
      throw lifecycleError('STALE_GENERATION', 'Package lifecycle destination already exists')
    }
    const destination = {
      ...clone(retainedHead),
      presentationId: destinationId,
      generation: 1,
      predecessorId: null,
      matrixAuthorityEpoch: next.matrixAuthorityEpoch,
      matrixAuthoritySubjects: createMatrixAuthoritySubjects(undefined, next.matrixAuthorityEpoch),
      fencingEpoch: store.fencingEpoch,
    }
    delete destination.pendingJournalHash
    let rebound = null
    if (authority) {
      rebound = rebindAuthority(
        authority,
        destinationId,
        destination.generation,
        `lifecycle-template-${hashRecord({ retainedOwner, destinationId })}`,
        { projection: options.projection }
      )
      destination.projectionRevisionId = hashRecord(rebound.projection)
      destination.sourceMapRevisionId = hashRecord(rebound.sourceMap)
      if (destination.packageRevisionId === destination.originalRevisionId) {
        destination.journalRevisionId = null
      }
      next.mutationResults.push(rebound)
    }
    next.heads.push(destination)
    for (const revisionId of revisionIdsFor(destination)) addOwner(next, revisionId, owner)
    if (options.compatibilityPresentation) {
      queueCompatibilityUpsert(next, {
        presentationId: destinationId,
        generation: destination.generation,
        updatedAt: options.updatedAt || options.compatibilityPresentation.updatedAt || new Date().toISOString(),
        presentation: {
          ...options.compatibilityPresentation,
          ...(rebound?.projection ? clone(rebound.projection) : {}),
          id: destinationId,
          pptxAggregateHead: clone(destination),
        },
      })
    }
  }, options)
  return store.metadata.state.heads.find((head) => head.presentationId === destinationId)
}

function getRestorableHead(store, presentationId, retainedOwner) {
  validateOwner(retainedOwner)
  const result = restorableHead(store.metadata.state, presentationId, retainedOwner)
  return result ? clone(result.retainedHead) : null
}

async function restoreForward(store, presentationId, retainedOwner, options = {}) {
  validateOwner(retainedOwner)
  const result = restorableHead(store.metadata.state, presentationId, retainedOwner)
  if (!result) {
    const rawRetainedHead = store.metadata.state.owners.find((item) =>
      item.ownerType === retainedOwner.ownerType &&
      item.ownerId === retainedOwner.ownerId &&
      item.retainedHead
    )?.retainedHead
    if (rawRetainedHead) {
      const rawHeadHash = hashRecord(rawRetainedHead)
      const matchingRecords = store.metadata.state.owners.filter((item) =>
        item.ownerType === retainedOwner.ownerType &&
        item.ownerId === retainedOwner.ownerId &&
        item.retainedHead && hashRecord(item.retainedHead) === rawHeadHash
      )
      if ([...revisionIdsFor(rawRetainedHead)].every((revisionId) =>
        matchingRecords.some((item) => item.revisionId === revisionId)
      ) && !hasRetainedRevisionIntegrity(
        store.metadata.state,
        rawRetainedHead,
        retainedOwner
      )) {
        throw lifecycleError(
          'CURRENT_SOURCE_AUTHORITY_UNAVAILABLE',
          'Package lifecycle retained authority is unavailable'
        )
      }
    }
    return null
  }
  const { retainedHead, current, retainedRevisionIds } = result
  const expectedCurrentHead = options.expectedCurrentHead || current
  if (options.expectedCurrentHead &&
      hashRecord(current) !== hashRecord(options.expectedCurrentHead)) {
    throw lifecycleError('STALE_GENERATION', 'Package lifecycle current head changed')
  }
  if (retainedHead.pendingJournalHash !== undefined || current.pendingJournalHash !== undefined) {
    throw lifecycleError(
      'PACKAGE_PENDING_PROJECTION',
      'Cannot restore a presentation while a pending package projection exists'
    )
  }
  const authority = committedAuthority(store.metadata.state, retainedHead)
  if (!authority && (retainedHead.projectionRevisionId || retainedHead.sourceMapRevisionId)) {
    throw lifecycleError(
      'CURRENT_SOURCE_AUTHORITY_UNAVAILABLE',
      'Package lifecycle retained authority is unavailable'
    )
  }

  await admit(store, options)
  await store.mutate((next) => {
    assertHeadUnchanged(next, expectedCurrentHead, presentationId)
    const liveRetained = restorableHead(next, presentationId, retainedOwner)
    if (!liveRetained || hashRecord(liveRetained.retainedHead) !== hashRecord(retainedHead)) {
      throw lifecycleError('STALE_GENERATION', 'Package lifecycle retained head changed')
    }
    const matrixAuthorityEpoch = next.matrixAuthorityEpoch + 1
    next.matrixAuthorityEpoch = matrixAuthorityEpoch
    const restoredHead = {
      ...clone(retainedHead),
      presentationId,
      generation: current.generation + 1,
      predecessorId: hashRecord(current),
      fencingEpoch: store.fencingEpoch,
      matrixAuthorityEpoch,
      matrixAuthoritySubjects: createMatrixAuthoritySubjects(undefined, matrixAuthorityEpoch),
    }
    delete restoredHead.pendingJournalHash
    let rebound = null
    if (authority) {
      rebound = rebindAuthority(
        authority,
        presentationId,
        restoredHead.generation,
        `lifecycle-restore-${hashRecord({ presentationId, retainedHead })}`,
        { projection: options.projection }
      )
      restoredHead.projectionRevisionId = hashRecord(rebound.projection)
      restoredHead.sourceMapRevisionId = hashRecord(rebound.sourceMap)
      if (restoredHead.packageRevisionId === restoredHead.originalRevisionId) {
        restoredHead.journalRevisionId = null
      }
      next.mutationResults.push(rebound)
    }
    next.heads = next.heads.map((head) => head.presentationId === presentationId
      ? restoredHead
      : {
        ...head,
        matrixAuthorityEpoch,
        matrixAuthoritySubjects: createMatrixAuthoritySubjects(undefined, matrixAuthorityEpoch),
      })
    // Epoch invalidation changes every exact compatibility fence, not just the
    // restored deck. Publish replacements atomically before old writes expire.
    for (const head of next.heads) {
      if (head.presentationId === presentationId && options.compatibilityPresentation) continue
      const queued = [...(next.compatibilityOutbox || [])].reverse().find((write) =>
        write.operation === 'upsert' && write.presentationId === head.presentationId &&
        write.headOnly !== true)
      const context = resolveEditedExportContext(next, head.presentationId)
      const projection = context.ok ? context.after : null
      const publication = projection
        ? mergeCompatibilityPresentation(queued?.presentation, projection)
        : queued?.presentation
      queueCompatibilityUpsert(next, {
        presentationId: head.presentationId,
        generation: head.generation,
        ...(queued?.updatedAt ? { updatedAt: queued.updatedAt } : {}),
        ...(context.ok ? { trustedImportMetadata: getTrustedImportMetadata(next, head) } : {}),
        headOnly: !publication,
        presentation: {
          ...(publication ? clone(publication) : {}),
          id: head.presentationId,
          pptxAggregateHead: clone(head),
        },
      })
    }
    next.owners = next.owners.filter((item) =>
      item.ownerType !== 'presentation' || item.ownerId !== presentationId
    )
    for (const revisionId of retainedRevisionIds) {
      addOwner(next, revisionId, {
        ownerType: 'presentation',
        ownerId: presentationId,
      })
    }
    if (options.compatibilityPresentation) {
      queueCompatibilityUpsert(next, {
        presentationId,
        generation: restoredHead.generation,
        updatedAt: options.updatedAt || options.compatibilityPresentation.updatedAt || new Date().toISOString(),
        trustedImportMetadata: getTrustedImportMetadata(next, restoredHead),
        presentation: {
          ...options.compatibilityPresentation,
          ...(rebound?.projection ? clone(rebound.projection) : {}),
          id: presentationId,
          pptxAggregateHead: clone(restoredHead),
        },
      })
    }
  }, options)
  return store.metadata.state.heads.find((item) => item.presentationId === presentationId)
}

module.exports = {
  duplicatePresentationOwner,
  instantiateRetainedHead,
  quarantinePresentation,
  restoreQuarantinedHead,
  getRestorableHead,
  restoreForward,
  retainHead,
}
